module.exports = "<ion-header class=\"interior-header\" dir=\"rtl\">\n  \n  <app-page-header titleKey=\"pageHeader.tuner-plus/shapes/shapes\" fallback=\"/TunerPlus\">\n\n  </app-page-header>\n</ion-header>\n\n<ion-content dir=\"rtl\" class=\"shapes-content\">\n  <div class=\"container\">\n    <div class=\"hero-banner\">\n      <span class=\"hero-chip\">📐 هندسه و الگوهای کلاس اول</span>\n      <h1>شکل‌شناسی و الگوهای هندسی</h1>\n      <p>شناخت چهار شکل اصلی (دایره، مثلث، مربع، مستطیل)، گوشه‌ها، لبه‌ها و اشیای مشابه در محیط زندگی کودک.</p>\n    </div>\n\n    <div class=\"shapes-workspace\">\n      <!-- ستون انتخاب اشکال -->\n      <div class=\"shapes-cards-col\">\n        <div \n          *ngFor=\"let s of shapes\" \n          class=\"shape-card\" \n          [class.active]=\"selectedShape.id === s.id\"\n          (click)=\"selectShape(s)\">\n          <span class=\"shape-icon\">{{ s.icon }}</span>\n          <h3>{{ s.name }}</h3>\n          <small>{{ s.sides === 0 ? 'بدون گوشه و لبه' : s.sides + ' لبه و ' + s.corners + ' گوشه' }}</small>\n        </div>\n      </div>\n\n      <!-- پنل بررسی و جزئیات شکل انتخابی -->\n      <div class=\"shape-details-col\" *ngIf=\"selectedShape\">\n        <div class=\"card-detail\">\n          <div class=\"badge-head\">ویژگی‌های هندسی:</div>\n          <div class=\"big-shape-view\">\n            <span class=\"big-icon\">{{ selectedShape.icon }}</span>\n            <h2>{{ selectedShape.name }}</h2>\n          </div>\n\n          <div class=\"specs-grid\">\n            <div class=\"spec-item\">\n              <span>تعداد لبه‌ها (ضلع):</span>\n              <b>{{ selectedShape.sides }}</b>\n            </div>\n            <div class=\"spec-item\">\n              <span>تعداد گوشه‌ها (رأس):</span>\n              <b>{{ selectedShape.corners }}</b>\n            </div>\n          </div>\n\n          <div class=\"examples-box\">\n            <h4>چیزهایی در اطراف ما که شبیه {{ selectedShape.name }} هستند:</h4>\n            <div class=\"examples-chips\">\n              <span *ngFor=\"let ex of selectedShape.examples\" class=\"ex-chip\">🔎 {{ ex }}</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- کوئیز تشخیص شکل بر اساس مشخصات -->\n        <div class=\"quiz-box\">\n          <div class=\"quiz-header\">\n            <h4>🎯 معمای هندسی: من چه شکلی هستم؟</h4>\n            <span class=\"score\">امتیاز: {{ quizScore }}</span>\n          </div>\n\n          <p class=\"riddle\">\n            «من <b>{{ shapes[quizCurrentIndex].sides }} لبه</b> و <b>{{ shapes[quizCurrentIndex].corners }} گوشه</b> دارم. مثل <b>{{ shapes[quizCurrentIndex].examples[0] }}</b> هستم.»\n          </p>\n\n          <div class=\"quiz-options\">\n            <button \n              *ngFor=\"let s of shapes\" \n              class=\"opt-btn\"\n              [class.correct]=\"quizAnswered && s.id === shapes[quizCurrentIndex].id\"\n              (click)=\"answerQuiz(s.id)\">\n              {{ s.name }}\n            </button>\n          </div>\n\n          <div *ngIf=\"quizAnswered\" class=\"quiz-feedback\">\n            <span *ngIf=\"quizFeedback === 'correct'\" class=\"correct-msg\">🎉 آفرین! درست حدس زدی.</span>\n            <span *ngIf=\"quizFeedback === 'wrong'\" class=\"wrong-msg\">❌ اشتباه بود، پاسخ {{ shapes[quizCurrentIndex].name }} است.</span>\n            <button class=\"next-btn\" (click)=\"newQuiz()\">معمای بعدی ❯</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <app-footer></app-footer>\n</ion-content>\n";

